<?php declare(strict_types=1);namespace App\Modules\ContractBoq\Services;use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\ContractBoq\DTOs\BoqItemData;use App\Modules\ContractBoq\DTOs\BoqSectionData;use App\Modules\ContractBoq\Repositories\ContractBoqRepository;final class ContractBoqService{public function __construct(private readonly ContractBoqRepository$r,private readonly Database$db,private readonly Auth$auth){}public function page(int$c):array{$contract=$this->contract($c);$boq=$this->r->boq($c);return['contract'=>$contract,'boq'=>$boq,'sections'=>$boq?$this->r->sections((int)$boq['id']):[],'total'=>$boq?$this->r->total((int)$boq['id']):'0.00','masters'=>$this->r->masters()];}public function start(int$c):void{$contract=$this->contract($c);$this->draftContract($contract);if($this->r->boq($c))throw new BusinessRuleException('تم بدء نطاق العقد بالفعل.');$this->r->create($c);}public function saveSection(int$c,BoqSectionData$d,?int$id=null):void{$b=$this->draftBoq($c);if($d->workSectionId!==null&&!$this->r->activeWorkSection($d->workSectionId))throw new BusinessRuleException('قسم الأعمال غير نشط أو غير موجود.');if($id===null)$this->r->addSection((int)$b['id'],$d);else{$s=$this->ownedSection($c,$id);$this->r->updateSection((int)$s['id'],$d);}}public function saveItem(int$c,BoqItemData$d,?int$id=null):void{$this->draftBoq($c);$this->ownedSection($c,$d->sectionId);$contract=$this->contract($c);$unit=$d->unitId===null?null:$this->r->activeUnit($d->unitId);if($d->unitId!==null&&!$unit)throw new BusinessRuleException('الوحدة غير نشطة أو غير موجودة.');if($d->costCodeId!==null&&!$this->r->activeCostCode($d->costCodeId))throw new BusinessRuleException('كود التكلفة غير متاح.');if($contract['pricing_method']==='boq'&&($unit===null||$d->quantity===null||$d->unitRate===null))throw new BusinessRuleException('بنود عقد جدول الكميات يجب أن تكون كاملة القياس والتسعير.');if($id===null)$this->r->addItem($d,$unit);else{$this->ownedItem($c,$id);$this->r->updateItem($id,$d,$unit);}}public function removeSection(int$c,int$id):void{$this->draftBoq($c);$this->ownedSection($c,$id);$this->db->transaction(fn()=>[$this->r->removeItems($id),$this->r->removeSection($id)]);}public function removeItem(int$c,int$id):void{$this->draftBoq($c);$this->ownedItem($c,$id);$this->r->removeItem($id);}public function discard(int$c):void{$b=$this->draftBoq($c);$this->draftContract($this->contract($c));if($this->r->countItems((int)$b['id'])>0||$this->r->sections((int)$b['id'])!==[])throw new BusinessRuleException('يمكن حذف نطاق اختياري فارغ فقط. احذف الأقسام أولًا.');$this->r->discard((int)$b['id']);}public function approve(int$c):void{$b=$this->draftBoq($c);$contract=$this->contract($c);$this->draftContract($contract);if($this->r->countItems((int)$b['id'])<1)throw new BusinessRuleException('لا يمكن اعتماد جدول كميات بلا بنود.');if($contract['pricing_method']==='boq'&&$this->r->incompleteItems((int)$b['id'])>0)throw new BusinessRuleException('جميع بنود BOQ يجب أن تكون مسعرة وقابلة للقياس.');$total=$this->r->total((int)$b['id']);$user=$this->auth->id()??throw new BusinessRuleException('تعذر تحديد المستخدم الحالي.');$this->db->transaction(fn()=>$this->r->approve((int)$b['id'],$user,$total,$contract['pricing_method']==='boq'));}private function contract(int$id):array{return$this->r->contract($id)??throw new BusinessRuleException('عقد العميل غير موجود.');}private function draftContract(array$c):void{if($c['status']!=='draft')throw new BusinessRuleException('لا يمكن تعديل النطاق الأصلي بعد تفعيل العقد.');}private function draftBoq(int$c):array{$b=$this->r->boq($c)??throw new BusinessRuleException('لم يتم بدء نطاق العقد.');if($b['status']!=='draft')throw new BusinessRuleException('جدول الكميات المعتمد غير قابل للتعديل.');return$b;}private function ownedSection(int$c,int$id):array{$s=$this->r->section($id);if(!$s||(int)$s['client_contract_id']!==$c)throw new BusinessRuleException('القسم لا يتبع هذا العقد.');return$s;}private function ownedItem(int$c,int$id):array{$i=$this->r->item($id);if(!$i||(int)$i['client_contract_id']!==$c)throw new BusinessRuleException('البند لا يتبع هذا العقد.');return$i;}}
